      if (url) {
        if (!checkNavigationOrPopup(url, 'window.open')) {
          console.warn('[Anti Pop-Under] Blocked window.open popunder to:', url);
          reportBlocked(url, 'window.open');
          return null;
        }

        // AGGRESSIVE WINDOW.OPEN BLOCKER:
        // Block any programmatic window.open to an external domain unless it's a known safe OAuth/login provider.
        try {
          const targetUrl = new URL(url, window.location.href);
          const currentUrl = new URL(window.location.href);
          const cleanDom = (d) => d.replace(/^www\./i, '');

          if (cleanDom(targetUrl.hostname) !== cleanDom(currentUrl.hostname)) {
            // Allow known safe OAuth/Login popups
            const safeDomains = ['facebook.com', 'google.com', 'twitter.com', 'github.com', 'apple.com', 'microsoft.com', 'accounts.google.com', 'api.twitter.com'];
            const isSafe = safeDomains.some(d => targetUrl.hostname.includes(d));

            if (!isSafe) {
              console.warn('[Anti Pop-Under] Blocked suspicious external window.open to:', url);
              reportBlocked(url, 'window.open.external');
              return null;
            }
          }
        } catch(e) {}
      }
      return originalWindowOpen.apply(this, arguments);
    };"

